20	constexpr int BLOCK_N = 64;    // kv rows per tile
21	constexpr int HEAD_DIM = 128;
22	constexpr int NUM_WARPS = 4;
23	constexpr int NUM_THREADS = NUM_WARPS * 32;
24	constexpr int PADDED_D = HEAD_DIM + 8;        // 16 B/row padding
25	constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;  // per K or V tile (bf16)
26	constexpr int O_ELEMS = BLOCK_M * PADDED_D;     // O staging (reuses Q buffer)
27	constexpr int SMEM_BYTES = 4 * TILE_ELEMS * 2 + O_ELEMS * 2;  // 87,040 B
28	
29	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
30	    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
31	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
32	}
33	__device__ __forceinline__ void cp_async_commit() {
34	    asm volatile("cp.async.commit_group;\n");
35	}
36	template<int N>
37	__device__ __forceinline__ void cp_async_wait() {
38	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
39	}
