// Probe: verify wmma m16n16k16 bf16 accumulator + matrix_a fragment layouts.
// C[16x16] = A[16x16] * B[16x16], A = identity => C == B.
// B[r][c] = r*1000 + c (distinct per element). Print where each thread's
// fragment element x[j] lands in (row, col) space.
#include <cstdio>
#include <cuda_bf16.h>
#include <mma.h>

using namespace nvcuda;

__global__ void probe(float* out_row, float* out_col) {
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> b_frag;
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> c_frag;

    __shared__ __nv_bfloat16 sA[16*16];
    __shared__ __nv_bfloat16 sB[16*16];
    for (int i = threadIdx.x; i < 256; i += 32) {
        int r = i / 16, c = i % 16;
        sA[r*16+c] = __float2bfloat16((r == c) ? 1.0f : 0.0f);
        sB[r*16+c] = __float2bfloat16((float)(r*1000 + c));
    }
    __syncthreads();

    wmma::load_matrix_sync(a_frag, sA, 16);
    wmma::load_matrix_sync(b_frag, sB, 16);
    wmma::fill_fragment(c_frag, 0.0f);
    wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);

    // Since C == B, element value r*1000+c tells us (r,c) of c_frag.x[j].
    for (int j = 0; j < 8; ++j) {
        float v = c_frag.x[j];
        int r = (int)(v / 1000.0f + 0.5f);
        int c = (int)(v - r*1000.0f + 0.5f);
        out_row[threadIdx.x*8 + j] = (float)r;
        out_col[threadIdx.x*8 + j] = (float)c;
    }
}

int main() {
    float *orow, *ocol;
    cudaMallocManaged(&orow, 32*8*sizeof(float));
    cudaMallocManaged(&ocol, 32*8*sizeof(float));
    probe<<<1,32>>>(orow, ocol);
    cudaDeviceSynchronize();
    // Print per-thread fragment layout: tid -> (r,c) for j=0..7
    for (int t = 0; t < 32; ++t) {
        printf("tid %2d: ", t);
        for (int j = 0; j < 8; ++j)
            printf("j%d=(%2.0f,%2.0f) ", j, orow[t*8+j], ocol[t*8+j]);
        printf("\n");
    }
    cudaFree(orow); cudaFree(ocol);
    return 0;
}

